package rules

import "testing"

// Cases ported from PHP-CS-Fixer's ModernizeStrposFixerTest (tests/Fixer/Alias), then
// invented ones (named "extra"/"analyzer"/...); every expected output is what
// PHP-CS-Fixer 3.95 produces for the input.
func TestModernizeStrposPhpCsFixerCases(t *testing.T) {
	t.Parallel()
	aliasRunUpstreamCases(t, ModernizeStrpos{}, []aliasUpstreamCase{
		{"yoda ===", nil, "<?php if (0 === strpos($haystack1, $needle)) {}", "<?php if (  str_starts_with($haystack1, $needle)) {}"},
		{"case insensitive yoda ===", map[string]any{"modernize_stripos": true}, "<?php if (0 === stripos($haystack1, $needle)) {}", "<?php if (  str_starts_with(strtolower($haystack1), strtolower($needle))) {}"},
		{"not zero yoda !==", nil, "<?php if (0 !== strpos($haystack2, $needle)) {}", "<?php if (  !str_starts_with($haystack2, $needle)) {}"},
		{"case insensitive not zero yoda !==", map[string]any{"modernize_stripos": true}, "<?php if (0 !== stripos($haystack2, $needle)) {}", "<?php if (  !str_starts_with(strtolower($haystack2), strtolower($needle))) {}"},
		{"false yoda ===", nil, "<?php if (false === strpos($haystack, $needle)) {}", "<?php if (  !str_contains($haystack, $needle)) {}"},
		{"case insensitive false yoda ===", map[string]any{"modernize_stripos": true}, "<?php if (false === stripos($haystack, $needle)) {}", "<?php if (  !str_contains(strtolower($haystack), strtolower($needle))) {}"},
		{"Fix#6", nil, "<?php if (strpos($haystack3, $needle) === 0) {}", "<?php if (str_starts_with($haystack3, $needle)  ) {}"},
		{"Fix#7", map[string]any{"modernize_stripos": true}, "<?php if (stripos($haystack3, $needle) === 0) {}", "<?php if (str_starts_with(strtolower($haystack3), strtolower($needle))  ) {}"},
		{"casing call", nil, "<?php if (STRPOS($haystack4, $needle) === 0) {}", "<?php if (str_starts_with($haystack4, $needle)  ) {}"},
		{"case insensitive casing call", map[string]any{"modernize_stripos": true}, "<?php if (STRIPOS($haystack4, $needle) === 0) {}", "<?php if (str_starts_with(strtolower($haystack4), strtolower($needle))  ) {}"},
		{"leading namespace", nil, "<?php if (\\strpos($haystack5, $needle) === 0) {}", "<?php if (\\str_starts_with($haystack5, $needle)  ) {}"},
		{"case insensitive leading namespace", map[string]any{"modernize_stripos": true}, "<?php if (\\stripos($haystack5, $needle) === 0) {}", "<?php if (\\str_starts_with(\\strtolower($haystack5), \\strtolower($needle))  ) {}"},
		{"leading namespace with yoda", nil, "<?php if (0 === \\strpos($haystack5, $needle)) {}", "<?php if (  \\str_starts_with($haystack5, $needle)) {}"},
		{"case insensitive leading namespace with yoda", map[string]any{"modernize_stripos": true}, "<?php if (0 === \\stripos($haystack5, $needle)) {}", "<?php if (  \\str_starts_with(\\strtolower($haystack5), \\strtolower($needle))) {}"},
		{"Fix#14", nil, "<?php if (strpos($haystack6, $needle) !== 0) {}", "<?php if (!str_starts_with($haystack6, $needle)  ) {}"},
		{"Fix#15", map[string]any{"modernize_stripos": true}, "<?php if (stripos($haystack6, $needle) !== 0) {}", "<?php if (!str_starts_with(strtolower($haystack6), strtolower($needle))  ) {}"},
		{"Fix#16", nil, "<?php if (\\strpos($haystack6, $needle) !== 0) {}", "<?php if (!\\str_starts_with($haystack6, $needle)  ) {}"},
		{"Fix#17", map[string]any{"modernize_stripos": true}, "<?php if (\\stripos($haystack6, $needle) !== 0) {}", "<?php if (!\\str_starts_with(\\strtolower($haystack6), \\strtolower($needle))  ) {}"},
		{"Fix#18", nil, "<?php if (0 !== \\strpos($haystack6, $needle)) {}", "<?php if (  !\\str_starts_with($haystack6, $needle)) {}"},
		{"Fix#19", map[string]any{"modernize_stripos": true}, "<?php if (0 !== \\stripos($haystack6, $needle)) {}", "<?php if (  !\\str_starts_with(\\strtolower($haystack6), \\strtolower($needle))) {}"},
		{"casing operand", nil, "<?php if (strpos($haystack7, $needle) !== FALSE) {}", "<?php if (str_contains($haystack7, $needle)  ) {}"},
		{"case insensitive casing operand", map[string]any{"modernize_stripos": true}, "<?php if (stripos($haystack7, $needle) !== FALSE) {}", "<?php if (str_contains(strtolower($haystack7), strtolower($needle))  ) {}"},
		{"Fix#22", nil, "<?php if (strpos($haystack8, $needle) === false) {}", "<?php if (!str_contains($haystack8, $needle)  ) {}"},
		{"Fix#23", map[string]any{"modernize_stripos": true}, "<?php if (stripos($haystack8, $needle) === false) {}", "<?php if (!str_contains(strtolower($haystack8), strtolower($needle))  ) {}"},
		{"Fix#24", nil, "<?php if (0 !== strpos($haystack9, $needle)) {}", "<?php if (  !str_starts_with($haystack9, $needle)) {}"},
		{"Fix#25", map[string]any{"modernize_stripos": true}, "<?php if (0 !== stripos($haystack9, $needle)) {}", "<?php if (  !str_starts_with(strtolower($haystack9), strtolower($needle))) {}"},
		{"Fix#26", nil, "<?php $a = strpos($haystack9a, $needle) !== 0;", "<?php $a = !str_starts_with($haystack9a, $needle)  ;"},
		{"Fix#27", map[string]any{"modernize_stripos": true}, "<?php $a = stripos($haystack9a, $needle) !== 0;", "<?php $a = !str_starts_with(strtolower($haystack9a), strtolower($needle))  ;"},
		{"comments inside, no spacing", nil, "<?php if (/* foo */false/* bar */!==strpos($haystack10,$a)) {}", "<?php if (/* foo *//* bar */str_contains($haystack10,$a)) {}"},
		{"case insensitive comments inside, no spacing", map[string]any{"modernize_stripos": true}, "<?php if (/* foo */false/* bar */!==stripos($haystack10,$a)) {}", "<?php if (/* foo *//* bar */str_contains(strtolower($haystack10),strtolower($a))) {}"},
		{"Fix#30", nil, "<?php $a = false === strpos($haystack11, $needle)?>", "<?php $a =   !str_contains($haystack11, $needle)?>"},
		{"Fix#31", map[string]any{"modernize_stripos": true}, "<?php $a = false === stripos($haystack11, $needle)?>", "<?php $a =   !str_contains(strtolower($haystack11), strtolower($needle))?>"},
		{"Fix#32", nil, "<?php $a = $input &&   strpos($input, $method) !== FALSE ? $input : null;", "<?php $a = $input &&   str_contains($input, $method)   ? $input : null;"},
		{"Fix#33", map[string]any{"modernize_stripos": true}, "<?php $a = $input &&   stripos($input, $method) !== FALSE ? $input : null;", "<?php $a = $input &&   str_contains(strtolower($input), strtolower($method))   ? $input : null;"},
		{"Fix#34", map[string]any{"modernize_stripos": true}, "<?php 0 !== stripos($file, $needle.\\DIRECTORY_SEPARATOR);", "<?php   !str_starts_with(strtolower($file), strtolower($needle.\\DIRECTORY_SEPARATOR));"},
		{"Fix#35", map[string]any{"modernize_stripos": true}, "<?php 0 !== stripos($file.\\DIRECTORY_SEPARATOR, $needle.\\DIRECTORY_SEPARATOR);", "<?php   !str_starts_with(strtolower($file.\\DIRECTORY_SEPARATOR), strtolower($needle.\\DIRECTORY_SEPARATOR));"},
		{"Fix#36", map[string]any{"modernize_stripos": true}, "<?php 0 !== stripos($file.\\DIRECTORY_SEPARATOR, $needle);", "<?php   !str_starts_with(strtolower($file.\\DIRECTORY_SEPARATOR), strtolower($needle));"},
		{"Fix#37", map[string]any{"modernize_stripos": true}, "<?php 0 === stripos(/** comm */ $file.\\DIRECTORY_SEPARATOR /* comm2 */, /* comm3 */ $needle // comm4\n            );", "<?php   str_starts_with(strtolower(/** comm */ $file.\\DIRECTORY_SEPARATOR /* comm2 */), /* comm3 */ strtolower($needle // comm4\n            ));"},
		{"Fix#38", nil, "<?php\n                $x = 1;\n                $x = \"strpos\";\n                // if (false === strpos($haystack12, $needle)) {}\n                /** if (false === strpos($haystack13, $needle)) {} */\n            ", "<?php\n                $x = 1;\n                $x = \"strpos\";\n                // if (false === strpos($haystack12, $needle)) {}\n                /** if (false === strpos($haystack13, $needle)) {} */\n            "},
		{"Fix#39", nil, "<?php\n                $x = 1;\n                $x = \"stripos\";\n                // if (false === strpos($haystack12, $needle)) {}\n                /** if (false === strpos($haystack13, $needle)) {} */\n            ", "<?php\n                $x = 1;\n                $x = \"stripos\";\n                // if (false === strpos($haystack12, $needle)) {}\n                /** if (false === strpos($haystack13, $needle)) {} */\n            "},
		{"disabled stripos (default)", nil, "<?php if (stripos($haystack3, $needle) === 0) {}", "<?php if (stripos($haystack3, $needle) === 0) {}"},
		{"disabled stripos", map[string]any{"modernize_stripos": false}, "<?php if (stripos($haystack3, $needle) === 0) {}", "<?php if (stripos($haystack3, $needle) === 0) {}"},
		{"different namespace", nil, "<?php if (a\\strpos($haystack14, $needle) === 0) {}", "<?php if (a\\strpos($haystack14, $needle) === 0) {}"},
		{"case insensitive different namespace", nil, "<?php if (a\\stripos($haystack14, $needle) === 0) {}", "<?php if (a\\stripos($haystack14, $needle) === 0) {}"},
		{"different namespace with yoda", nil, "<?php if (0 === a\\strpos($haystack14, $needle)) {}", "<?php if (0 === a\\strpos($haystack14, $needle)) {}"},
		{"case insensitive different namespace with yoda", nil, "<?php if (0 === a\\stripos($haystack14, $needle)) {}", "<?php if (0 === a\\stripos($haystack14, $needle)) {}"},
		{"non condition (hardcoded)", nil, "<?php $x = strpos('foo', 'f');", "<?php $x = strpos('foo', 'f');"},
		{"case insensitive non condition (hardcoded)", nil, "<?php $x = stripos('foo', 'f');", "<?php $x = stripos('foo', 'f');"},
		{"non condition", nil, "<?php $x = strpos($haystack15, $needle) ?>", "<?php $x = strpos($haystack15, $needle) ?>"},
		{"case insensitive non condition", nil, "<?php $x = stripos($haystack15, $needle) ?>", "<?php $x = stripos($haystack15, $needle) ?>"},
		{"none zero int", nil, "<?php if (1 !== strpos($haystack16, $needle)) {}", "<?php if (1 !== strpos($haystack16, $needle)) {}"},
		{"case insensitive none zero int", nil, "<?php if (1 !== stripos($haystack16, $needle)) {}", "<?php if (1 !== stripos($haystack16, $needle)) {}"},
		{"greater condition", nil, "<?php if (strpos($haystack17, $needle) > 0) {}", "<?php if (strpos($haystack17, $needle) > 0) {}"},
		{"case insensitive greater condition", nil, "<?php if (stripos($haystack17, $needle) > 0) {}", "<?php if (stripos($haystack17, $needle) > 0) {}"},
		{"lesser condition", nil, "<?php if (0 < strpos($haystack18, $needle)) {}", "<?php if (0 < strpos($haystack18, $needle)) {}"},
		{"case insensitive lesser condition", nil, "<?php if (0 < stripos($haystack18, $needle)) {}", "<?php if (0 < stripos($haystack18, $needle)) {}"},
		{"no argument", nil, "<?php $z = strpos();", "<?php $z = strpos();"},
		{"case insensitive no argument", nil, "<?php $z = stripos();", "<?php $z = stripos();"},
		{"one argument", nil, "<?php if (0 === strpos($haystack1)) {}", "<?php if (0 === strpos($haystack1)) {}"},
		{"case insensitive one argument", nil, "<?php if (0 === stripos($haystack1)) {}", "<?php if (0 === stripos($haystack1)) {}"},
		{"3 arguments", nil, "<?php if (0 === strpos($haystack1, $a, $b)) {}", "<?php if (0 === strpos($haystack1, $a, $b)) {}"},
		{"case insensitive 3 arguments", nil, "<?php if (0 === stripos($haystack1, $a, $b)) {}", "<?php if (0 === stripos($haystack1, $a, $b)) {}"},
		{"higher precedence 1", nil, "<?php if (4 + 0 !== strpos($haystack9, $needle)) {}", "<?php if (4 + 0 !== strpos($haystack9, $needle)) {}"},
		{"case insensitive higher precedence 1", nil, "<?php if (4 + 0 !== stripos($haystack9, $needle)) {}", "<?php if (4 + 0 !== stripos($haystack9, $needle)) {}"},
		{"higher precedence 2", nil, "<?php if (!false === strpos($haystack, $needle)) {}", "<?php if (!false === strpos($haystack, $needle)) {}"},
		{"case insensitive higher precedence 2", nil, "<?php if (!false === stripos($haystack, $needle)) {}", "<?php if (!false === stripos($haystack, $needle)) {}"},
		{"higher precedence 3", nil, "<?php $a = strpos($haystack, $needle) === 0 + 1;", "<?php $a = strpos($haystack, $needle) === 0 + 1;"},
		{"case insensitive higher precedence 3", nil, "<?php $a = stripos($haystack, $needle) === 0 + 1;", "<?php $a = stripos($haystack, $needle) === 0 + 1;"},
		{"higher precedence 4", nil, "<?php $a = strpos($haystack, $needle) === 0 > $b;", "<?php $a = strpos($haystack, $needle) === 0 > $b;"},
		{"case insensitive higher precedence 4", nil, "<?php $a = stripos($haystack, $needle) === 0 > $b;", "<?php $a = stripos($haystack, $needle) === 0 > $b;"},
		{"extra #1", nil, "<?php\nnamespace Acme;\n\nuse function Other\\strpos;\n\nif (strpos($haystack, $needle) === 0) {}", "<?php\nnamespace Acme;\n\nuse function Other\\strpos;\n\nif (strpos($haystack, $needle) === 0) {}"},
		{"extra #2", nil, "<?php\nnamespace Acme;\n\nfunction strpos($a, $b) {}\n\nif (strpos($haystack, $needle) !== false) {}\nif (\\strpos($haystack, $needle) !== false) {}", "<?php\nnamespace Acme;\n\nfunction strpos($a, $b) {}\n\nif (strpos($haystack, $needle) !== false) {}\nif (\\str_contains($haystack, $needle)  ) {}"},
		{"extra #3", nil, "<?php\nif (\\false === strpos($haystack, $needle)) {}\nif (strpos($haystack, $needle) === \\false) {}\nif (strpos($haystack, $needle, 1) === 0) {}\nif (strpos($haystack, $needle) == 0) {}\nif (strpos($haystack, $needle) === 0 . '') {}\nif ($x . 0 === strpos($haystack, $needle)) {}\nif (strpos($haystack, $needle) > 0) {}\n$a = strpos($haystack, $needle) !== false && strpos($haystack, $other) === false;\n$b = !strpos($haystack, $needle) === 0;\n$c = (strpos($haystack, $needle)) === 0;\n$d = $obj->strpos($a, $b) === 0;", "<?php\nif (!\\  str_contains($haystack, $needle)) {}\nif (strpos($haystack, $needle) === \\false) {}\nif (strpos($haystack, $needle, 1) === 0) {}\nif (strpos($haystack, $needle) == 0) {}\nif (strpos($haystack, $needle) === 0 . '') {}\nif ($x . 0 === strpos($haystack, $needle)) {}\nif (strpos($haystack, $needle) > 0) {}\n$a = str_contains($haystack, $needle)   && !str_contains($haystack, $other)  ;\n$b = !str_starts_with($haystack, $needle)  ;\n$c = (strpos($haystack, $needle)) === 0;\n$d = $obj->strpos($a, $b) === 0;"},
		{"stripos #1", map[string]any{"modernize_stripos": true}, "<?php \\stripos($a,$b) === 0;", "<?php \\str_starts_with(\\strtolower($a),\\strtolower()$b)  ;"},
		{"stripos #2", map[string]any{"modernize_stripos": true}, "<?php stripos($a, $b /* c */) === 0;", "<?php str_starts_with(strtolower($a), strtolower($b /* c */))  ;"},
		{"stripos #3", map[string]any{"modernize_stripos": true}, "<?php \\stripos($a, /* c */ $b) === 0;", "<?php \\str_starts_with(\\strtolower($a), /* c */ \\strtolower($b))  ;"},
		{"stripos #4", map[string]any{"modernize_stripos": true}, "<?php if (\\false === stripos($a, $b)) {}", "<?php if (!\\  str_contains(strtolower($a), strtolower($b))) {}"},
		{"stripos #5", map[string]any{"modernize_stripos": true}, "<?php if (0 === \\stripos($a , $b , )) {}", "<?php if (  \\str_starts_with(\\strtolower($a ), \\strtolower($b ), )) {}"},
		{"in a backtick literal", nil, "<?php $x = `echo {$o->m(strpos($a, $b) === 0)} ${a} \"q\"`;", "<?php $x = `echo {$o->m(str_starts_with($a, $b)  )} ${a} \"q\"`;"},
	})
}
